  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `user_id` bigint NOT NULL COMMENT '提问用户ID',
  `user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '提问用户名',
  `question` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '问题',
  `answer` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '回答（AI结论summary，无结论时为空）',
  `result_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '查询结果JSON（columns/rows/sql/emptyReason，供回放）',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '状态（0成功 1失败）',
  `create_time` datetime DEFAULT NULL COMMENT '提问时间',
  PRIMARY KEY (`id`),
  KEY `idx_nlq_history_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='AI数据查询历史记录表';
