--
-- Table structure for table `dms_pm_plan`
--

DROP TABLE IF EXISTS `dms_pm_plan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dms_pm_plan` (
  `plan_id` bigint NOT NULL AUTO_INCREMENT COMMENT '计划ID',
  `plan_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '计划名称',
  `equipment_id` bigint DEFAULT NULL COMMENT '设备ID（为空则按分类）',
  `category_id` bigint DEFAULT NULL COMMENT '设备分类ID',
  `trigger_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '触发类型（字典 dms_pm_trigger_type）',
  `cycle_value` int DEFAULT NULL COMMENT '周期值',
  `cycle_unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '周期单位（天/月/小时/件）',
  `task_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '任务清单（JSON数组）',
  `spare_part_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '备件清单（JSON数组）',
  `estimated_hours` decimal(10,2) DEFAULT NULL COMMENT '预估工时',
  `advance_days` int DEFAULT '3' COMMENT '提前生成天数',
  `auto_assign` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '是否自动派工（0否 1是）',
  `assignee_id` bigint DEFAULT NULL COMMENT '默认派工人ID',
  `assignee_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '默认派工人名称',
  `last_execute_time` datetime DEFAULT NULL COMMENT '上次执行时间',
  `next_execute_time` datetime DEFAULT NULL COMMENT '下次执行时间',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`plan_id`),
  KEY `idx_pm_equipment` (`equipment_id`),
  KEY `idx_pm_category` (`category_id`),
  KEY `idx_pm_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='PM预防性维护计划表';
/*!40101 SET character_set_client = @saved_cs_client */;

