DROP TABLE IF EXISTS `dms_spare_part_stock`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dms_spare_part_stock` (
  `stock_id` bigint NOT NULL AUTO_INCREMENT COMMENT '库存ID',
  `part_id` bigint NOT NULL COMMENT '备件ID（关联dms_spare_part.part_id）',
  `warehouse_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '默认备件库' COMMENT '仓库名称',
  `storage_location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '存放位置',
  `current_stock` decimal(18,2) DEFAULT '0.00' COMMENT '当前库存',
  `lock_qty` decimal(18,2) DEFAULT '0.00' COMMENT '锁定库存',
  `stock_min` decimal(18,2) DEFAULT '0.00' COMMENT '库存下限',
  `stock_max` decimal(18,2) DEFAULT '0.00' COMMENT '库存上限',
