  `direction` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '方向 DEBIT借/CREDIT贷',
  `amount` decimal(14,2) NOT NULL COMMENT '金额（正数，红字用 direction 表达）',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'CNY' COMMENT '币种（V1 固定 CNY）',
  `exchange_rate` decimal(18,6) DEFAULT '1.000000' COMMENT '汇率（V1 固定 1）',
  `tax_amount` decimal(14,2) DEFAULT '0.00' COMMENT '税额',
  `aux_customer_id` bigint DEFAULT NULL COMMENT '辅助核算-客户',
  `aux_supplier_id` bigint DEFAULT NULL COMMENT '辅助核算-供应商',
  `aux_dept_id` bigint DEFAULT NULL COMMENT '辅助核算-部门',
  `aux_project_id` bigint DEFAULT NULL COMMENT '辅助核算-项目',
  `summary` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '摘要',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '删除标志',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`entry_id`),
  KEY `idx_voucher` (`voucher_id`),
  KEY `idx_subject_period` (`account_code`,`period`),
  KEY `idx_aux_customer` (`aux_customer_id`),
  KEY `idx_aux_supplier` (`aux_supplier_id`),
  KEY `idx_entry_dept` (`dept_id`,`period`),
  CONSTRAINT `chk_entry_amount` CHECK ((`amount` <> 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='记账凭证分录表';
