--
-- Table structure for table `mk_opportunity`
--

DROP TABLE IF EXISTS `mk_opportunity`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mk_opportunity` (
  `opportunity_id` bigint NOT NULL AUTO_INCREMENT COMMENT '商机ID',
  `opportunity_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商机编号',
  `opportunity_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商机名称',
  `customer_id` bigint NOT NULL COMMENT '客户ID',
  `contact_id` bigint DEFAULT NULL COMMENT '主要联系人ID',
  `lead_id` bigint DEFAULT NULL COMMENT '来源线索ID',
  `opportunity_source` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '商机来源（字典）',
  `expected_amount` decimal(14,2) NOT NULL COMMENT '预计金额',
  `expected_date` date NOT NULL COMMENT '预计成交日期',
  `stage_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'stage1' COMMENT '销售阶段编码',
  `stage_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '销售阶段名称',
  `win_rate` int DEFAULT '10' COMMENT '赢率（%）',
  `weighted_amount` decimal(14,2) DEFAULT '0.00' COMMENT '加权金额',
  `opportunity_status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '商机状态（0进行中 1已赢单 2已输单）',
  `competitor` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '竞争对手',
  `pain_point` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '客户痛点',
  `solution` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '解决方案',
  `lost_reason` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '输单原因',
  `lost_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '输单说明',
  `actual_amount` decimal(14,2) DEFAULT NULL COMMENT '实际成交金额',
  `actual_date` date DEFAULT NULL COMMENT '实际成交日期',
  `user_id` bigint DEFAULT NULL COMMENT '负责人ID',
  `dept_id` bigint DEFAULT NULL COMMENT '部门ID',
  `next_action` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '下一步行动',
  `next_time` datetime DEFAULT NULL COMMENT '下次行动时间',
  `stage_enter_time` datetime DEFAULT NULL COMMENT '进入当前阶段时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '删除标志',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`opportunity_id`),
  UNIQUE KEY `uk_opportunity_no` (`opportunity_no`),
  KEY `idx_opp_customer` (`customer_id`),
  KEY `idx_opp_stage` (`stage_code`),
  KEY `idx_opp_status` (`opportunity_status`),
  KEY `idx_opp_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='商机表';
/*!40101 SET character_set_client = @saved_cs_client */;

