INSERT INTO `sys_config` VALUES (1,'主框架页-默认皮肤样式名称','sys.index.skinName','skin-blue','Y','admin','2026-07-13 11:25:53','',NULL,'蓝色 skin-blue、绿色 skin-green、紫色 skin-purple、红色 skin-red、黄色 skin-yellow'),(2,'用户管理-账号初始密码','sys.user.initPassword','123456','Y','admin','2026-07-13 11:25:53','',NULL,'初始化密码 123456'),(3,'主框架页-侧边栏主题','sys.index.sideTheme','theme-dark','Y','admin','2026-07-13 11:25:53','',NULL,'深色主题theme-dark，浅色主题theme-light'),(4,'账号自助-验证码开关','sys.account.captchaEnabled','false','Y','admin','2026-07-13 11:25:53','',NULL,'是否开启验证码功能（true开启，false关闭）'),(5,'账号自助-是否开启用户注册功能','sys.account.registerUser','false','Y','admin','2026-07-13 11:25:53','',NULL,'是否开启注册用户功能（true开启，false关闭）'),(6,'用户登录-黑名单列表','sys.login.blackIPList','','Y','admin','2026-07-13 11:25:53','',NULL,'设置登录IP黑名单限制，多个匹配项以;分隔，支持匹配（*通配、网段）'),(7,'用户管理-初始密码修改策略','sys.account.initPasswordModify','1','Y','admin','2026-07-13 11:25:53','',NULL,'0：初始密码修改策略关闭，没有任何提示，1：提醒用户，如果未修改初始密码，则在登录时就会提醒修改密码对话框'),(8,'用户管理-账号密码更新周期','sys.account.passwordValidateDays','0','Y','admin','2026-07-13 11:25:53','',NULL,'密码更新周期（填写数字，数据初始化值为0不限制，若修改必须为大于0小于365的正整数），如果超过这个周期登录系统时，则在登录时就会提醒修改密码对话框'),(9,'用户管理-密码字符范围','sys.account.chrtype','0','Y','admin','2026-07-13 11:25:53','',NULL,'默认任意字符范围，0任意（密码可以输入任意字符），1数字（密码只能为0-9数字），2英文字母（密码只能为a-z和A-Z字母），3字母和数字（密码必须包含字母，数字）,4字母数字和特殊字符（目前支持的特殊字符包括：~!@#$%^&*()-=_+）'),(104,'AI智能报修开关','dms.ai.repair_assistant','true','Y','admin','2026-07-17 08:29:53','admin','2026-09-15 16:04:48','智能报修助手开关'),(105,'AI智能派工开关','dms.ai.dispatch_recommend','true','Y','admin','2026-07-17 08:29:53','admin','2026-09-15 16:04:48','智能派工推荐开关'),(106,'AI知识问答开关','dms.ai.knowledge_qa','true','Y','admin','2026-07-17 08:29:53','admin','2026-09-15 16:04:48','维修知识问答开关'),(108,'是否启用企业信息查询','pms.enterprise.lookup.enabled','true','Y','admin','2026-07-27 18:35:30','admin','2026-07-27 23:18:41','企业信息查询功能开关'),(109,'企业查询API提供商','pms.enterprise.lookup.provider','qichacha','Y','admin','2026-07-27 18:35:30','admin','2026-07-27 23:18:41','tianyancha=天眼