--
-- Table structure for table `sys_table_config`
--

DROP TABLE IF EXISTS `sys_table_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_table_config` (
  `config_id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `table_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '页面标识（如 pms_eval_index）',
  `col_prop` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '列属性名（如 supplierName）',
  `col_width` int DEFAULT NULL COMMENT '列宽（像素），NULL表示未设置',
  `config_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'U' COMMENT '配置类型：G=全局（管理员设置），U=个人（用户自定义）',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID（config_type=U时有效，G时为NULL）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `col_visible` tinyint(1) DEFAULT NULL COMMENT '列是否可见：1=可见，0=隐藏，NULL=未设置',
  `col_order` int DEFAULT NULL COMMENT '列顺序（从0开始，按数字排序决定列的左右位置）',
  PRIMARY KEY (`config_id`),
  UNIQUE KEY `uk_table_col_type_user` (`table_key`,`col_prop`,`config_type`,`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1523 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='表格列宽配置表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `sys_table_config`
--

LOCK TABLES `sys_table_config` WRITE;
/*!40000 ALTER TABLE `sys_table_config` DISABLE KEYS */;
