CREATE TABLE `wms_wave` (
  `wave_id` bigint NOT NULL AUTO_INCREMENT COMMENT '波次ID',
  `wave_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '波次号',
  `wave_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '波次名称',
  `warehouse_id` bigint NOT NULL COMMENT '仓库ID',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '状态（0待拣货 1拣货中 2已完成 3已作废）',
